import{_ as t,I as o,g as r,j as a}from"./chunks/framework.CjoWWfVe.js";const p=JSON.parse('{"title":"Production (Workbench)","description":"Managing the order queue, dynamic material reservation, and finished goods release.","frontmatter":{"title":"Production (Workbench)","description":"Managing the order queue, dynamic material reservation, and finished goods release.","order":7},"headers":[],"relativePath":"docs/spaces/production/workbench.md","filePath":"docs/spaces/production/workbench.md"}'),n={name:"docs/spaces/production/workbench.md"};function s(i,e,c,l,d,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="🔨-production-the-workbench-manufacturing-queue" tabindex="-1">🔨 Production: The Workbench &amp; Manufacturing Queue <a class="header-anchor" href="#🔨-production-the-workbench-manufacturing-queue" aria-label="Permalink to &quot;🔨 Production: The Workbench &amp; Manufacturing Queue&quot;">​</a></h1><p>The <strong>&quot;Production&quot; (Workbench)</strong> tab is your control center. All product batches scheduled in the <strong>Calculator</strong> tab end up here.</p><p>The core feature of the Workbench in OmniCraft ERP is <strong>dynamic planning without rigid locks</strong>. Adding an order to the workbench <em>does not</em> deduct materials from the warehouse instantly. Instead, the program creates a &quot;soft reserve.&quot;</p><hr><h2 id="🚦-dynamic-queue-priorities" tabindex="-1">🚦 Dynamic Queue &amp; Priorities <a class="header-anchor" href="#🚦-dynamic-queue-priorities" aria-label="Permalink to &quot;🚦 Dynamic Queue &amp; Priorities&quot;">​</a></h2><p>The manufacturing queue operates on a <strong>cascade top-down reservation</strong> principle. The program analyzes the raw material stock and distributes it among orders depending on their position (priority) in the list.</p><p>You can manage the priority using the <strong>Up</strong> (↑) and <strong>Down</strong> (↓) arrow buttons on each order card.</p><h3 id="how-the-statuses-work" tabindex="-1">How the statuses work: <a class="header-anchor" href="#how-the-statuses-work" aria-label="Permalink to &quot;How the statuses work:&quot;">​</a></h3><ul><li>✅ <strong>Secured with Materials:</strong> There is enough free raw stock in the warehouse to complete this order.</li><li>⚠️ <strong>Material Deficit:</strong> The program shows exactly which material is missing and how much is needed to start.</li></ul><blockquote><p><strong>Real-Life Example:</strong> Suppose you have exactly 10 square feet of leather left in stock. Two orders are queued on the workbench: a <em>Bag</em> (requires 8 sq ft) and a <em>Backpack</em> (requires 9 sq ft). If the <em>Bag</em> is positioned higher in the queue than the <em>Backpack</em>, the program will reserve the leather for the <em>Bag</em> (Status: Secured). The <em>Backpack</em> will show a Deficit (missing 7 sq ft). However, if you click the <strong>&quot;Up&quot;</strong> arrow on the <em>Backpack</em> and raise its priority, the program instantly recalculates your stock: the <em>Backpack</em> takes the leather (Status: Secured), and the <em>Bag</em> slips into a Deficit (missing 7 sq ft).</p></blockquote><p>This allows you to outline a schedule weeks in advance, even if the necessary materials are not yet in the warehouse. As you record batch purchases in the <strong>Materials</strong> tab, the red deficit statuses on the Workbench will automatically turn into green secured statuses.</p><hr><h2 id="🏭-completing-production-finished-goods-release" tabindex="-1">🏭 Completing Production (Finished Goods Release) <a class="header-anchor" href="#🏭-completing-production-finished-goods-release" aria-label="Permalink to &quot;🏭 Completing Production (Finished Goods Release)&quot;">​</a></h2><p>Once you have physically finished crafting a batch, click the <strong>&quot;Complete&quot;</strong> button. At this exact millisecond, the program performs several crucial background operations:</p><ol><li><strong>Actual Raw Materials Deduction:</strong> The reserved materials are permanently deducted from your warehouse stock (under the <strong>Materials</strong> tab) with a log entry in your inventory log. Negative balances are permitted—if you forgot to record a purchase, the warehouse stock will slide into a negative, but production will not be blocked.</li><li><strong>Cost Price Locking:</strong> The program takes a &quot;snapshot&quot; of the current costs. It combines the current cost of raw materials, your active master labor rate, and overhead expenses, and <strong>permanently freezes</strong> this figure as the cost price for this specific batch.</li><li><strong>Showcase Entry (FIFO):</strong> Completed items are added to your showroom stock (the <strong>Finished Goods</strong> tab) as a distinct batch.</li></ol><div class="info custom-block"><p class="custom-block-title">Cost Price Protection (FIFO)</p><p>Suppose yesterday you crafted a wallet from cheap leather (cost price: <code>$10</code>), and today you crafted the exact same wallet from expensive leather (cost price: <code>$15</code>). Both wallets will sit in your finished goods inventory. Upon sale, the program will deduct them using the <strong>FIFO (First In, First Out)</strong> method—the old <code>$10</code> wallet is deducted first, and the new <code>$15</code> wallet second. This ensures cost-accounting accuracy for your reported net profit.</p></div><hr><h2 id="❌-cancelling-an-order" tabindex="-1">❌ Cancelling an Order <a class="header-anchor" href="#❌-cancelling-an-order" aria-label="Permalink to &quot;❌ Cancelling an Order&quot;">​</a></h2><p>If your plans change, you can click the <strong>&quot;Cancel&quot;</strong> button. The order will disappear from the workbench, and all materials it had reserved will immediately be released and allocated to the next orders in the queue.</p><div class="warning custom-block"><p class="custom-block-title">Limitations in the Free Version</p><p>If you are using the free version of OmniCraft ERP and have reached the limit of 20 processed sales, the <strong>Production</strong> tab will switch to Read-Only mode. A red warning banner will appear, and the <strong>&quot;Complete&quot;</strong> button will be locked until you activate a license key. You will still be able to cancel scheduled orders, but you will not be able to release new finished goods.</p></div>',20)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
